<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityRolesRoleAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the PlatformIdentityRolesRoleAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class PlatformIdentityRolesRoleAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRole returns null on a freshly created holder.
     */
    public function testRoleNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityRolesRoleAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRoleAssigned());
        $this->assertNull($holder->getRole());
    }
}
class ImplWithPlatformIdentityRolesRoleAttributeHolderUnitTest
{
    use PlatformIdentityRolesRoleAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRoleRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRole();
    }
}
